(function(root){'use strict';const clone=x=>JSON.parse(JSON.stringify(x));
function prepare(record,version,user,business){if(record.owner!==user||record.business!==business)throw Error('只能基于本人当前业务的版本继续修改。');const source=(record.versions||[]).find(x=>x.version===version);if(!source)throw Error('该历史版本不存在，请重新打开记录。');if(!source.content)throw Error('该版本没有可修改正文。');return {recordId:record.id,baseVersion:version,title:source.title||record.title,content:source.content,sources:clone(source.sources||[]),requirements:source.requirements??record.requirements??'',retain:source.retain??record.retain??'',inputType:source.inputType||record.inputType||'draft',outputType:source.outputType||record.outputType||'speech',legacySettings:source.requirements===undefined||!source.sources?.length};}
function stamp(record,baseVersion,previousVersion,previousLike){if(record.version<=previousVersion)return false;record.versionLineage=record.versionLineage||{};record.versionLineage[record.version]={basedOnVersion:baseVersion,at:new Date().toISOString()};record.personalMarksByVersion=record.personalMarksByVersion||{};if(previousLike)record.personalMarksByVersion[previousVersion]=true;record.liked=false;record.assessmentStatus='stale';return true;}
root.VersionBranch={prepare,stamp};if(typeof module!=='undefined')module.exports=root.VersionBranch;
})(globalThis);
